public class LazyRecipeLayoutList<T>
implements IRecipeLayoutList {
    private final IRecipeManager recipeManager;
    private final IRecipeCategory<T> recipeCategory;
    private final IFocusGroup focusGroup;
    private final IRecipeLayoutWithButtonsFactory recipeLayoutFactory;
    private final List<IRecipeLayoutWithButtons<?>> results;
    private final List<IRecipeLayoutWithButtons<?>> craftMissing;
    private final Iterator<T> unsortedIterator;
    private final int size;
    private final boolean sortCraftable;

    LazyRecipeLayoutList(Set<RecipeSorterStage> recipeSorterStages, IFocusedRecipes<T> selectedRecipes, IFocusGroup focusGroup, BookmarkList bookmarkList, IRecipeManager recipeManager, IRecipeLayoutWithButtonsFactory recipeLayoutFactory) {
        boolean matchingBookmarks = recipeSorterStages.contains((Object)RecipeSorterStage.BOOKMARKED);
        this.sortCraftable = recipeSorterStages.contains((Object)RecipeSorterStage.CRAFTABLE);
        this.recipeManager = recipeManager;
        this.recipeCategory = selectedRecipes.getRecipeCategory();
        this.focusGroup = focusGroup;
        this.recipeLayoutFactory = recipeLayoutFactory;
        this.results = new ArrayList();
        this.craftMissing = new ArrayList();
        List<T> recipes = selectedRecipes.getRecipes();
        this.size = recipes.size();
        if (matchingBookmarks) {
            RecipeType<T> recipeType = this.recipeCategory.getRecipeType();
            recipes = new ArrayList<T>(recipes);
            Iterator<T> iterator = recipes.iterator();
            while (iterator.hasNext()) {
                T recipe = iterator.next();
                RecipeBookmark<T, ?> recipeBookmark = bookmarkList.getMatchingBookmark(recipeType, recipe);
                if (recipeBookmark == null) continue;
                IRecipeLayoutWithButtons<T> recipeLayoutWithButtons = this.createRecipeLayoutWithButtons(recipe, recipeBookmark);
                this.results.add(recipeLayoutWithButtons);
                iterator.remove();
            }
        }
        this.unsortedIterator = recipes.iterator();
    }

    private IRecipeLayoutWithButtons<T> createRecipeLayoutWithButtons(T recipe, @Nullable RecipeBookmark<?, ?> recipeBookmark) {
        IRecipeLayoutDrawable<T> recipeLayout = this.recipeManager.createRecipeLayoutDrawableOrShowError(this.recipeCategory, recipe, this.focusGroup);
        return this.recipeLayoutFactory.create(recipeLayout, recipeBookmark);
    }

    @Override
    public int size() {
        return this.size;
    }

