    @Override
    public void tick(@Nullable AbstractContainerMenu container) {
        this.calculateNextResult(container);
    }

    private boolean calculateNextResult(@Nullable AbstractContainerMenu container) {
        boolean matchingCraftable = this.isMatchingCraftable(container);
        LocalPlayer player = Minecraft.m_91087_().f_91074_;
        while (this.unsortedIterator.hasNext()) {
            T recipe = this.unsortedIterator.next();
            IRecipeLayoutWithButtons<T> next = this.createRecipeLayoutWithButtons(recipe, null);
            if (matchingCraftable) {
                next.updateTransferButton(container, (Player)player);
                int missingCountHint = next.getMissingCountHint();
                if (missingCountHint == 0) {
                    this.results.add(next);
                    return true;
                }
                this.craftMissing.add(next);
                continue;
            }
            this.results.add(next);
            return true;
        }
        if (!this.craftMissing.isEmpty()) {
            this.craftMissing.sort(RecipeSortUtil.getCraftableComparator());
            this.results.addAll(this.craftMissing);
            this.craftMissing.clear();
            return true;
        }
        return false;
    }

    private boolean isMatchingCraftable(@Nullable AbstractContainerMenu container) {
        if (!this.sortCraftable || container == null) {
            return false;
        }
        IRecipeTransferManager recipeTransferManager = Internal.getJeiRuntime().getRecipeTransferManager();
        return recipeTransferManager.getRecipeTransferHandler(container, this.recipeCategory).isPresent();
    }
}

