final class RegisteredIngredientIndex<T> {
    private static final Logger LOGGER = LogManager.getLogger();
    private final IIngredientHelper<T> ingredientHelper;
    private final Map<Object, ITypedIngredient<T>> ingredientsByUid = new LinkedHashMap<Object, ITypedIngredient<T>>();
    private final Map<Object, List<ITypedIngredient<T>>> ingredientsByGroupingUid = new HashMap<Object, List<ITypedIngredient<T>>>();

    RegisteredIngredientIndex(IIngredientHelper<T> ingredientHelper) {
        this.ingredientHelper = ingredientHelper;
    }

    public void addAll(Collection<ITypedIngredient<T>> ingredients) {
        ingredients.forEach(this::add);
    }

    public void add(ITypedIngredient<T> ingredient) {
        @Nullable Object uid = this.getUid(ingredient);
        if (uid == null) {
            return;
        }
        @Nullable Object groupingUid = this.getGroupingUid(ingredient);
        ITypedIngredient<T> previous = this.ingredientsByUid.put(uid, ingredient);
        if (previous == null) {
            this.addToGroup(groupingUid, ingredient);
            return;
        }
        @Nullable Object previousGroupingUid = this.getGroupingUid(previous);
        if (Objects.equals(previousGroupingUid, groupingUid)) {
            this.replaceInGroup(groupingUid, previous, ingredient);
        } else {
            this.removeFromGroup(previousGroupingUid, previous);
            this.addToGroup(groupingUid, ingredient);
        }
    }

    public void removeAll(Collection<ITypedIngredient<T>> ingredients) {
        ingredients.forEach(this::remove);
    }

